@Serializable
data class OrderDto(val id: String, val total: Double)

sealed interface Result<out T> {
    data class Ok<T>(val value: T) : Result<T>
    data class Err(val message: String) : Result<Nothing>
}

fun Application.ordersModule(repo: OrderRepository) {
    routing {
        get("/orders/{id}") {
            val id = call.parameters["id"] ?: return@get call.respond(HttpStatusCode.BadRequest)
            when (val result = repo.find(id)) {
                is Result.Ok -> call.respond(OrderDto(result.value.id, result.value.total))
                is Result.Err -> call.respondText(result.message, status = HttpStatusCode.NotFound)
            }
        }
        post("/orders") {
            val body = call.receive<OrderDto>()
            val saved = repo.save(body)
            println("Saved order ${saved.id}")
            call.respond(HttpStatusCode.Created, saved)
        }
    }
}

