@dataclass
class Order:
    id: str
    total: float
    paid: bool = False


class OrderClient:
    def __init__(self, base_url: str, timeout: float = 2.5):
        self.base_url = base_url
        self.timeout = timeout

    def fetch(self, order_id: str) -> Optional[Order]:
        resp = requests.get(f"{self.base_url}/orders/{order_id}", timeout=self.timeout)
        if resp.status_code == 404:
            return None
        resp.raise_for_status()
        data = resp.json()
        return Order(**data)

    def total_paid(self, ids: list[str]) -> float:
        orders = [self.fetch(i) for i in ids]
        return sum(o.total for o in orders if o and o.paid)


