type Repo struct {
	db *sql.DB
}

var ErrNotFound = errors.New("order not found")

func NewRepo(db *sql.DB) *Repo {
	return &Repo{db: db}
}

func (r *Repo) Find(ctx context.Context, id string) (*Order, error) {
	row := r.db.QueryRowContext(ctx, "SELECT id, total, placed_at FROM orders WHERE id = $1", id)
	var o Order
	if err := row.Scan(&o.ID, &o.Total, &o.PlacedAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("find order %s: %w", id, err)
	}
	return &o, nil
}

func (r *Repo) Count(ctx context.Context) (n int, err error) {
	err = r.db.QueryRowContext(ctx, "SELECT count(*) FROM orders").Scan(&n)
	return
}

