use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use axum::{extract::State, routing::get, Json, Router};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Order {
    id: u64,
    total: f64,
}

type Store = Arc<Mutex<HashMap<u64, Order>>>;

async fn list(State(store): State<Store>) -> Json<Vec<Order>> {
    let guard = store.lock().unwrap();
    Json(guard.values().cloned().collect())
}

impl Order {
    fn discounted(&self, pct: f64) -> Order {
        Order { total: self.total * (1.0 - pct / 100.0), ..self.clone() }
    }
}

#[tokio::main]
async fn main() {
    let store: Store = Arc::new(Mutex::new(HashMap::new()));
    let app = Router::new().route("/orders", get(list)).with_state(store);
    let listener = tokio::net::TcpListener::bind("0.0.0.0:8080").await.unwrap();
    println!("listening on {}", listener.local_addr().unwrap());
    axum::serve(listener, app).await.unwrap();
}

