namespace orders {

class Order {
public:
    Order(std::string id, double total) : id_(std::move(id)), total_(total) {}
    const std::string& id() const { return id_; }
    double total() const noexcept { return total_; }

private:
    std::string id_;
    double total_;
};

class Repository {
public:
    void add(std::shared_ptr<Order> order) {
        items_[order->id()] = std::move(order);
    }

    std::shared_ptr<Order> find(const std::string& id) const {
        auto it = items_.find(id);
        return it == items_.end() ? nullptr : it->second;
    }

private:
    std::unordered_map<std::string, std::shared_ptr<Order>> items_;
};

}  // namespace orders

